     3	import hotel.rooms.Room;
     4	import java.math.BigDecimal;
     5	import java.math.RoundingMode;
     6	import java.time.LocalDate;
     7	import java.time.Month;
     8	import java.util.List;
     9	
    10	/**
    11	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
    12	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
    13	 * (half-even) at every step.
    14	 */
    15	public final class PriceCalculator {
    16	
    17	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.25");
    18	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
    19	
    20	    /** Holy Week: Palm Sunday through Easter Sunday, both nights included. */
    21	    private record Period(LocalDate first, LocalDate last) {
    22	        boolean contains(LocalDate date) {
    23	            return !date.isBefore(first) && !date.isAfter(last);
    24	        }
    25	    }
    26	
    27	    /** Only these years are known; later years must be added. */
    28	    private static final List<Period> HOLY_WEEKS = List.of(
    29	            new Period(LocalDate.of(2027, 3, 21), LocalDate.of(2027, 3, 28)),
    30	            new Period(LocalDate.of(2028, 4, 9), LocalDate.of(2028, 4, 16)));
    31	
    32	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
    33	        int nights = 0;
    34	        BigDecimal subtotal = cents(BigDecimal.ZERO);
    35	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    36	            subtotal = subtotal.add(nightPrice(room, night));
    37	            nights++;
    38	        }
    39	        BigDecimal discount = switch (ratePlan) {
    40	            case STANDARD -> cents(BigDecimal.ZERO);
    41	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
    42	        };
    43	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
    44	    }
    45	
    46	    BigDecimal nightPrice(Room room, LocalDate night) {
    47	        BigDecimal nightlyRate = room.nightlyRate();
    48	        if (isHighSeason(night)) {
    49	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
    50	        }
    51	        return cents(nightlyRate);
    52	    }
    53	
    54	    /** High season: from December 15 to the end of February, the whole of July, and Holy Week. */
    55	    static boolean isHighSeason(LocalDate date) {
    56	        Month month = date.getMonth();
    57	        return HOLY_WEEKS.stream().anyMatch(week -> week.contains(date))
    58	                || month == Month.JANUARY
    59	                || month == Month.FEBRUARY
    60	                || month == Month.JULY
    61	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
    62	    }
    63	
    64	    static BigDecimal cents(BigDecimal value) {
    65	        return value.setScale(2, RoundingMode.HALF_EVEN);
    66	    }
    67	}
