 1	package hotel.reservations;
 2	
 3	import static org.junit.jupiter.api.Assertions.assertEquals;
 4	import static org.junit.jupiter.api.Assertions.assertFalse;
 5	import static org.junit.jupiter.api.Assertions.assertTrue;
 6	
 7	import hotel.rooms.Room;
 8	import hotel.rooms.RoomType;
 9	import java.math.BigDecimal;
10	import java.time.LocalDate;
11	import org.junit.jupiter.api.Test;
12	
13	class PriceCalculatorTest {
14	
15	    private final PriceCalculator calculator = new PriceCalculator();
16	    private final Room standardRoom = new Room(101, RoomType.STANDARD, 2, new BigDecimal("249.90"));
17	    private final Room suite = new Room(301, RoomType.SUITE, 4, new BigDecimal("579.90"));
18	
19	    @Test
20	    void lowSeasonNightsCostTheNightlyRate() {
21	        Price price = calculator.calculate(
22	                standardRoom, LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 13), RatePlan.STANDARD);
23	
24	        assertEquals(3, price.nights());
25	        assertEquals(new BigDecimal("749.70"), price.subtotal());
26	        assertEquals(new BigDecimal("0.00"), price.discount());
27	        assertEquals(new BigDecimal("749.70"), price.total());
28	    }
29	
30	    @Test
31	    void highSeasonStartsOnDecember15() {
32	        Price price = calculator.calculate(
33	                standardRoom, LocalDate.of(2027, 12, 14), LocalDate.of(2027, 12, 16), RatePlan.STANDARD);
34	
35	        // December 14: 249.90; December 15: 249.90 + 25% = 312.38
36	        assertEquals(new BigDecimal("562.28"), price.total());
37	    }
38	
39	    @Test
40	    void highSeasonEndsWithFebruary() {
41	        Price price = calculator.calculate(
42	                standardRoom, LocalDate.of(2028, 2, 29), LocalDate.of(2028, 3, 2), RatePlan.STANDARD);
43	
44	        // February 29 (leap year): 312.38; March 1: 249.90
45	        assertEquals(new BigDecimal("562.28"), price.total());
46	    }
47	
48	    @Test
49	    void julyIsHighSeason() {
50	        assertFalse(PriceCalculator.isHighSeason(LocalDate.of(2027, 6, 30)));
51	        assertTrue(PriceCalculator.isHighSeason(LocalDate.of(2027, 7, 1)));
52	        assertTrue(PriceCalculator.isHighSeason(LocalDate.of(2027, 7, 31)));
53	        assertFalse(PriceCalculator.isHighSeason(LocalDate.of(2027, 8, 1)));
54	    }
55	
56	    @Test
57	    void nonRefundableTakes15PercentOffRoundingHalfEven() {
58	        Price price = calculator.calculate(
59	                standardRoom, LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 11), RatePlan.NON_REFUNDABLE);
60	
61	        // 15% of 249.90 = 37.485, which rounds half-even to 37.48 (half-up would give 37.49)
62	        assertEquals(new BigDecimal("37.48"), price.discount());
63	        assertEquals(new BigDecimal("212.42"), price.total());
64	    }
65	
66	    @Test
67	    void nonRefundableDiscountIsOnTheHighSeasonPrice() {
68	        Price price = calculator.calculate(
69	                suite, LocalDate.of(2027, 1, 5), LocalDate.of(2027, 1, 9), RatePlan.NON_REFUNDABLE);
70	
71	        // 4 nights of 579.90 + 25% = 724.875, half-even 724.88 each
72	        assertEquals(new BigDecimal("2899.52"), price.subtotal());
73	        assertEquals(new BigDecimal("434.93"), price.discount());
74	        assertEquals(new BigDecimal("2464.59"), price.total());
75	    }
76	
77	    @Test
78	    void holyWeekIsHighSeasonFromPalmSundayToEasterSunday() {
79	        assertFalse(PriceCalculator.isHighSeason(LocalDate.of(2027, 3, 20)));
